（1）The area of the pan is A, and the width to length ratio of the oven is W/L.
Below is the C++ code for calculating the wasted rate and scorched rate of the best
shape .
#include <iostream>
#include <fstream>
#include <cmath>
#define Pi 3.1415926536
using namespace std;
double temp[1002][1002][2];
double wlratio = 0.618,A = 7000;
int w = 100,l;
double initemp = 20,maxtemp = 180, ripetemp = 60, overtemp = 177;
double F = 0.22;
int ans[1002],i,j;
double dist(int a,int b,double c,double d){//count the dist
      return sqrt(((a-c)*(a-c)+(b-d)*(b-d)));
}
bool check(int i,int j,int type,int a){//check if (i,j)is in the shape(a)
      switch (type){
           case 1:
                  if (i<=a && j<=a || i>w-a && j<=a || i<=a && j>l-a || i>w-a && j>l-a){
                         if (dist(i,j,a,a)<a || dist(i,j,a,l-a+1)<a ||dist(i,j,w-a+1,a)<a||dist(i,j,w-a+1,l-
      a+1)<a) return true;
                         return false;
                  }
                  return true;
                  break;
           case 2:
                  if (i<=a || i>w-a){
                         double c = sqrt((a*a-l*l/4)*1.0);
                         if (dist(i,j,a-c,l/2)+dist(i,j,a+c,l/2)>2*a && dist(i,j,w-a-c,l/2)+dist(i,j,w-
      a+c,l/2)>2*a) return false;
                         return true;
                  }
                  return true;
           case 3:

