                double c = sqrt((a*a-l*l/4)*1.0);
                if (dist(i,j,a-c,l/2)+dist(i,j,a+c,l/2)>2*a) return false;
                return true;
     }
}
double getans(int type,int a){

     w = static_cast<int>(sqrt((A+(4-Pi)*a*a)/wlratio));
           l = w*wlratio;
           for (int i=0;i<=w+1;i++)
           for (int j=0;j<=l+1;j++){
                 temp[i][j][0] = temp[i][j][1] = maxtemp;
           }
     for (int i=1;i<=w;i++)
           for (int j=1;j<=l;j++){
                 temp[i][j][0] = check(i,j,type,a)?initemp:maxtemp;
           }

     int t=0;
     while (true){
           int number = 0;
           for (int i=1;i<=w;i++)
                  for (int j=1;j<=l;j++)if (check(i,j,type,a)){
                        temp[i][j][1-t] = F*(temp[i-1][j][t] + temp[i+1][j][t] + temp[i][j-1][t] +
     temp[i][j+1][t])+(1-4*F)*temp[i][j][t];
                        if (temp[i][j][1-t] <ripetemp) number ++;
                  }
           if (number == 0) break;
           t=1-t;
     }

     int number = 0,sum = 0;
     for (int i=1;i<=w;i++){
           for (int j=1;j<=l;j++){
                 if (check(i,j,type,a)) sum++;
           }
     }
     for (int i=1;i<=w;i++){
           for (int j=1;j<=l;j++){
                 if (check(i,j,type,a)&&temp[i][j][1-t]>overtemp) number++;
           }
     }
     return number*100.0/sum;

}
double getrate(int type,int a){
     w = static_cast<int>(sqrt((A+(4-Pi)*a*a)/wlratio));
           l = w*wlratio;
     int sum = 0,x = 200,y = 200,xx = 0,yy = 0;
     for (int i=1;i<=w;i++){
           for (int j=1;j<=l;j++){
                 if (check(i,j,type,a)) {
                       sum++;

