                      if (i<x) x = i;
                      if (i>xx) xx = i;
                      if (j<y) y = j;
                      if (j>yy) yy = j;
           }}
      }
      return 100 - sum * 100.0/((xx-x+1)*(yy-y+1));

}
int main(){
     if (wlratio>1) wlratio = 1/wlratio;
     ofstream output("result.txt");

      int type=1;
      for (int a=0;a<=l/2;a++){
            output<<type<<' '<<a<<' '<<getans(type,a)<<' '<<getrate(type,a)<<endl;
      }

      type = 2;
      for (int a=l/2+1;a<=w/2;a++){
            output<<type<<' '<<a<<' '<<getans(type,a)<<' '<<getrate(type,a)<<endl;
            }
      type = 3;
      for (int a=w/2;a>sqrt(A/Pi);a--){
            output<<type<<' '<<a<<' '<<getans(type,a)<<' '<<getrate(type,a)<<endl;
      }
      return 0;
}


(2) The area of the pan is A, print the width to length ratio and the radius of the pan
to calculate the area of the rectangle that can exactly wrap the shape. Here is the
code.
#include <iostream>
#include <fstream>
using namespace std;
int main(){
      while (true){
           int a,A=7000;
           double c,Pi=3.1415926536;
           double w,l;
           while (cin>>c>>a){
                 w = (sqrt((A+(4-Pi)*a*a)/c));
                 l = w*c;
                 cout<<w<<' '<<l<<endl;
           }
      }
}


