int main(){
     ifstream input("resultl.txt");
     ofstream output("result.txt");
     double a[1000],b[1000];

      int n=0,mina=0,minb=0;
      while (!input.eof()){
           input>>a[n]>>a[n]>>a[n]>>b[n];

           if (a[n]<=a[mina]) mina = n;
           if (b[n]<b[minb]) minb = n;
           n++;
      }
      output<<a[mina]<<' '<<b[mina]<<endl;
      int p=mina;
      while (p!=minb) {
           double k,kmin=1000000; int kk;
           for (int i=0;i<n;i++) if (a[i]>a[p]){
                 if (abs(a[i]-a[p])>0.000001) k=(b[i]-b[p])/(a[i]-a[p]);
                 if (k<kmin) { kmin = k; kk = i;};
           }
           p=kk;
           output<<a[p]<<' '<<b[p]<<endl;
      }
      return 0;
}


(4) The code to calculate shape of different weight P.
#include <iostream>
#include <fstream>
using namespace std;
int main(){
       ofstream output("outgold.txt");
double a[200],b[200],c[200],p;
int n,i;
cin>>n;
       for (i=0;i<n;i++) cin>>a[i]>>b[i];

      int pre = -1;
      for (p=0;p<1;p+=0.00001){
           int min = 0;
           for (i=0;i<n;i++){
                 c[i] = a[i]*p+b[i]*(1-p);
                 if (c[i]<c[min]) min = i;
                 }
           if (min!=pre){
                 output<<p<<' '<<min<<endl;
                 pre= min;
           }
      }
      return 0;
      }
